import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const hasOwn = (object, key) => Object.prototype.hasOwnProperty.call(object, key);

function invalid() {
  throw new Error('Invalid context packet input');
}

function validate(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) invalid();
  if (!Array.isArray(sections)) invalid();

  const ids = new Set();
  const validated = [];
  for (let index = 0; index < sections.length; index += 1) {
    if (!hasOwn(sections, index)) invalid();
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) invalid();
    if (!hasOwn(section, 'id') || !hasOwn(section, 'text') ||
        !hasOwn(section, 'priority') || !hasOwn(section, 'required')) invalid();

    const {id, text, priority, required} = section;
    if (typeof id !== 'string' || id.length === 0 || typeof text !== 'string' ||
        !Number.isSafeInteger(priority) || priority < 0 || typeof required !== 'boolean' ||
        ids.has(id)) invalid();
    ids.add(id);
    validated.push({id, text, priority, required, index});
  }
  return validated;
}

export function packContext(sections, maxBytes) {
  const entries = validate(sections, maxBytes);
  let remaining = maxBytes;
  const frames = [];
  const included = [];
  const optional = [];
  const omittedFlags = new Array(entries.length).fill(false);

  for (const entry of entries) {
    const frame = `### ${JSON.stringify(entry.id)}\n${entry.text}\n`;
    const cost = Buffer.byteLength(frame, 'utf8');
    entry.frame = frame;
    entry.cost = cost;
    if (entry.required) {
      if (cost > remaining) throw new Error('Required sections exceed maxBytes');
      remaining -= cost;
      frames.push(frame);
      included.push(entry.id);
    } else {
      optional.push(entry);
    }
  }

  optional.sort((left, right) => right.priority - left.priority || left.index - right.index);
  for (const entry of optional) {
    if (entry.cost <= remaining) {
      remaining -= entry.cost;
      frames.push(entry.frame);
      included.push(entry.id);
    } else {
      omittedFlags[entry.index] = true;
    }
  }

  const omitted = entries.filter((entry) => omittedFlags[entry.index]).map((entry) => entry.id);
  const text = frames.join('');
  return {text, bytes: Buffer.byteLength(text, 'utf8'), included, omitted};
}

function runCli() {
  if (process.argv.length !== 3) throw new Error('Expected exactly one input JSON file');
  const source = fs.readFileSync(process.argv[2], 'utf8');
  const input = JSON.parse(source);
  if (input === null || typeof input !== 'object' || Array.isArray(input)) invalid();
  const result = packContext(input.sections, input.maxBytes);
  process.stdout.write(`${JSON.stringify(result)}\n`);
}

const invokedFile = process.argv[1] && path.resolve(process.argv[1]);
if (invokedFile === fileURLToPath(import.meta.url)) {
  try {
    runCli();
  } catch (error) {
    const message = error instanceof Error && error.message ? error.message : 'Invalid input';
    process.stderr.write(`${message}\n`);
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {packContext} from '../context-packet.js';

const script = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../context-packet.js');

function run(args) {
  return spawnSync(process.execPath, [script, ...args], {encoding: 'utf8'});
}

test('safe-integer budgets are enforced by the API', () => {
  assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER), {text: '', bytes: 0, included: [], omitted: []});
  assert.throws(() => packContext([], Number.MAX_SAFE_INTEGER + 1), Error);
});

test('CLI has exact success and failure streams', () => {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'context-packet-'));
  try {
    const valid = path.join(directory, 'valid.json');
    const invalid = path.join(directory, 'invalid.json');
    fs.writeFileSync(valid, JSON.stringify({sections: [], maxBytes: 0, ignored: true}), 'utf8');
    fs.writeFileSync(invalid, '{', 'utf8');

    const success = run([valid]);
    assert.equal(success.status, 0);
    assert.equal(success.stdout, '{"text":"","bytes":0,"included":[],"omitted":[]}\n');
    assert.equal(success.stderr, '');

    for (const result of [run([]), run([path.join(directory, 'missing.json')]), run([invalid])]) {
      assert.equal(result.status, 2);
      assert.equal(result.stdout, '');
      assert.notEqual(result.stderr, '');
    }

    fs.writeFileSync(valid, JSON.stringify({sections: [{id: 'r', text: 'x', priority: 0, required: true}], maxBytes: 0}), 'utf8');
    const overflow = run([valid]);
    assert.equal(overflow.status, 2);
    assert.equal(overflow.stdout, '');
    assert.notEqual(overflow.stderr, '');
  } finally {
    fs.rmSync(directory, {recursive: true, force: true});
  }
});

